"""Domain exceptions and the single error envelope returned by every endpoint.

    {"code": "invalid_transition", "message": "...", "details": {...}}

Services raise DomainError subclasses; the handler below turns them into responses.
"""

from rest_framework import status
from rest_framework.exceptions import ValidationError
from rest_framework.response import Response
from rest_framework.views import exception_handler as drf_exception_handler


class DomainError(Exception):
    """Base class for business-rule failures raised by services."""

    status_code = status.HTTP_400_BAD_REQUEST
    code = "domain_error"
    default_message = "The request could not be completed."

    def __init__(self, message=None, *, code=None, details=None):
        self.message = message or self.default_message
        self.code = code or self.code
        self.details = details or {}
        super().__init__(self.message)


class RuleViolation(DomainError):
    """A business rule rejected the input (HTTP 422)."""

    status_code = status.HTTP_422_UNPROCESSABLE_ENTITY
    code = "rule_violation"
    default_message = "A business rule was violated."


class InvalidTransition(DomainError):
    """The object is not in a state that allows this action (HTTP 409)."""

    status_code = status.HTTP_409_CONFLICT
    code = "invalid_transition"
    default_message = "This action is not allowed in the current state."


class NotAllowed(DomainError):
    """The actor may not perform this action (HTTP 403)."""

    status_code = status.HTTP_403_FORBIDDEN
    code = "not_allowed"
    default_message = "You are not allowed to do this."


def api_exception_handler(exc, context):
    if isinstance(exc, DomainError):
        return Response(
            {"code": exc.code, "message": exc.message, "details": exc.details},
            status=exc.status_code,
        )

    response = drf_exception_handler(exc, context)
    if response is None:
        return None

    data = response.data
    if isinstance(exc, ValidationError):
        code, message, details = "validation_error", "Invalid input.", data
    else:
        detail = data.get("detail") if isinstance(data, dict) else None
        message = str(detail) if detail else "Request failed."
        code = getattr(detail, "code", None) or getattr(exc, "default_code", "error")
        details = {}
    response.data = {"code": code, "message": message, "details": details}
    return response
